import React, { useState, useEffect } from 'react';
import {
  Users,
  UserCheck,
  BookOpen,
  FolderCheck,
  CheckSquare,
  Clock,
  DollarSign,
  AlertCircle,
  TrendingUp,
} from 'lucide-react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
  ArcElement,
  PointElement,
  LineElement,
} from 'chart.js';
import { Doughnut, Bar } from 'react-chartjs-2';
import StatCard from '../../components/common/StatCard';
import LoadingSpinner from '../../components/common/LoadingSpinner';
import { getDashboardStats } from '../../services/userService';

ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
  ArcElement,
  PointElement,
  LineElement
);

const AdminDashboard = () => {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchStats = async () => {
      try {
        const res = await getDashboardStats();
        setData(res);
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    };
    fetchStats();
  }, []);

  if (loading) return <LoadingSpinner fullScreen />;

  const cards = data?.cards || {};
  const charts = data?.charts || {};

  // Chart 1: Department Distribution (Doughnut)
  const deptLabels = (charts.deptDistribution || []).map((d) => d._id);
  const deptCounts = (charts.deptDistribution || []).map((d) => d.count);

  const deptChartData = {
    labels: deptLabels.length ? deptLabels : ['Editorial', 'Graphics', 'Printing', 'Warehouse'],
    datasets: [
      {
        data: deptCounts.length ? deptCounts : [4, 2, 3, 2],
        backgroundColor: [
          '#6366F1',
          '#8B5CF6',
          '#0EA5E9',
          '#10B981',
          '#F59E0B',
          '#EF4444',
          '#EC4899',
        ],
        borderWidth: 0,
      },
    ],
  };

  // Chart 2: Task Status Breakdown
  const taskStatusLabels = (charts.taskStatusCounts || []).map((t) => t._id);
  const taskStatusCounts = (charts.taskStatusCounts || []).map((t) => t.count);

  const taskChartData = {
    labels: taskStatusLabels.length ? taskStatusLabels : ['Pending', 'In Progress', 'Submitted', 'Approved'],
    datasets: [
      {
        label: 'Tasks Count',
        data: taskStatusCounts.length ? taskStatusCounts : [3, 5, 2, 8],
        backgroundColor: ['#F59E0B', '#3B82F6', '#8B5CF6', '#10B981'],
        borderWidth: 0,
      },
    ],
  };

  // Chart 3: Project Progress
  const projLabels = (charts.projectProgress || []).map((p) => p.bookName);
  const projProgress = (charts.projectProgress || []).map((p) => p.completionPercentage);

  const projChartData = {
    labels: projLabels.length ? projLabels : ['Book A', 'Book B', 'Book C'],
    datasets: [
      {
        label: 'Completion %',
        data: projProgress.length ? projProgress : [65, 80, 90],
        backgroundColor: 'rgba(99, 102, 241, 0.7)',
        borderRadius: 8,
      },
    ],
  };

  return (
    <div className="page-container">
      <div className="page-header">
        <div>
          <h1 className="page-title">Executive Admin Dashboard</h1>
          <p className="page-subtitle">Pustak Market Book Publication & Distribution Overview</p>
        </div>
      </div>

      {/* 10 Metric Cards */}
      <div className="grid-cards">
        <StatCard
          icon={Users}
          title="Total Employees"
          value={cards.totalEmployees || 0}
          color="#6366F1"
        />
        <StatCard
          icon={UserCheck}
          title="Active Employees"
          value={cards.activeEmployees || 0}
          color="#10B981"
        />
        <StatCard
          icon={BookOpen}
          title="Total Projects"
          value={cards.totalProjects || 0}
          color="#0EA5E9"
        />
        <StatCard
          icon={FolderCheck}
          title="Active Projects"
          value={cards.activeProjects || 0}
          color="#8B5CF6"
        />
        <StatCard
          icon={CheckSquare}
          title="Total Tasks"
          value={cards.totalTasks || 0}
          color="#3B82F6"
        />
        <StatCard
          icon={Clock}
          title="Pending Tasks"
          value={cards.pendingTasks || 0}
          color="#F59E0B"
        />
        <StatCard
          icon={TrendingUp}
          title="Completed Tasks"
          value={cards.completedTasks || 0}
          color="#10B981"
        />
        <StatCard
          icon={UserCheck}
          title="Attendance Today"
          value={cards.attendanceToday || 0}
          color="#EC4899"
        />
        <StatCard
          icon={DollarSign}
          title="Monthly Salary Expense"
          value={`$${(cards.monthlySalaryExpense || 0).toLocaleString()}`}
          color="#8B5CF6"
        />
        <StatCard
          icon={AlertCircle}
          title="Pending Payments"
          value={`$${(cards.pendingPayments || 0).toLocaleString()}`}
          color="#EF4444"
        />
      </div>

      {/* Visual Analytics Charts */}
      <div className="grid-charts">
        {/* Department Distribution */}
        <div className="card">
          <h3 style={{ fontSize: '1.1rem', fontWeight: 700, marginBottom: '16px' }}>
            Department Workforce Distribution
          </h3>
          <div style={{ height: '280px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <Doughnut
              data={deptChartData}
              options={{
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                  legend: { position: 'right', labels: { color: 'var(--text-main)' } },
                },
              }}
            />
          </div>
        </div>

        {/* Task Breakdown */}
        <div className="card">
          <h3 style={{ fontSize: '1.1rem', fontWeight: 700, marginBottom: '16px' }}>
            Publication Task Status Breakdown
          </h3>
          <div style={{ height: '280px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <Doughnut
              data={taskChartData}
              options={{
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                  legend: { position: 'right', labels: { color: 'var(--text-main)' } },
                },
              }}
            />
          </div>
        </div>

        {/* Project Progress */}
        <div className="card" style={{ gridColumn: '1 / -1' }}>
          <h3 style={{ fontSize: '1.1rem', fontWeight: 700, marginBottom: '16px' }}>
            Active Publication Projects Completion Tracker
          </h3>
          <div style={{ height: '300px' }}>
            <Bar
              data={projChartData}
              options={{
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                  y: {
                    max: 100,
                    ticks: { color: 'var(--text-secondary)', callback: (v) => `${v}%` },
                    grid: { color: 'var(--border-color)' },
                  },
                  x: {
                    ticks: { color: 'var(--text-secondary)' },
                    grid: { color: 'var(--border-color)' },
                  },
                },
                plugins: {
                  legend: { display: false },
                },
              }}
            />
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;
